insert into passages (id, text, difficulty_level, b, active) values
('1dafb6c2-8aea-4bd5-b242-f11b48bb84eb', 'The tragedy of the commons, a concept popularized by ecologist Garrett Hardin in 1968, describes a situation in which individuals acting in their own rational self-interest deplete a shared resource, even though doing so is contrary to the long-term interests of the group as a whole. Hardin''s original example involved herders sharing a common pasture, each of whom benefits individually from adding more animals to graze, while the costs of overgrazing are distributed among all users of the pasture. Because each individual bears only a fraction of the collective cost while capturing the full benefit of their own actions, the rational choice for each herder is to keep adding animals, ultimately leading to the resource''s collapse. Economists have since applied this framework to numerous real-world problems, including overfishing, deforestation, and atmospheric pollution. However, the political economist Elinor Ostrom later challenged the assumption that such tragedies are inevitable, demonstrating through extensive fieldwork that communities have often developed sophisticated, self-governing institutions capable of managing shared resources sustainably without resorting to either privatization or centralized government control. Ostrom''s research, which earned her the Nobel Memorial Prize in Economic Sciences, suggested that the tragedy of the commons is not an inescapable fate but rather a failure of institutional design.', 5, 2.0, true);
insert into questions (id, type, text, passage_id, options, correct_answer, explanation, a, b, c, difficulty_level, created_by, hint, active) values
('078bd965-bd9a-4174-973f-6476f6a0f63d', 'sentence_completion', 'The committee''s decision was widely seen as a ___ to public pressure rather than a genuine policy shift.', NULL, '[{"id": "d", "text": "capitulation"}, {"id": "b", "text": "commitment"}, {"id": "c", "text": "innovation"}, {"id": "a", "text": "refutation"}]'::jsonb, 0, '{"strategy": "rather than a genuine policy shift = ולא שינוי מדיניות אמיתי. איזו מילה מתארת כניעה ללחץ ציבורי?", "correct_reason": "capitulation = כניעה. תגובה ללחץ ולא שינוי אמיתי היא כניעה.", "options_analysis": ["נכון! capitulation = כניעה — מתאים לתגובה ללחץ ולא לשינוי אמיתי", "commitment = מחויבות — הפוך, מרמז על שינוי אמיתי", "innovation = חדשנות — לא קשור לתגובה ללחץ", "refutation = הפרכה — לא קשור להקשר"]}', 1.48, 2.0, 0.25, 5, 'ai', NULL, true),
('1e149710-c60e-4be4-be0a-8cb3fd458f8e', 'sentence_completion', 'Her argument, though eloquently presented, ultimately rested on ___ evidence.', NULL, '[{"id": "d", "text": "irrefutable"}, {"id": "b", "text": "spurious"}, {"id": "c", "text": "conclusive"}, {"id": "a", "text": "overwhelming"}]'::jsonb, 1, '{"strategy": "though eloquently presented, ultimately = למרות ניסוח רהוט, בסופו של דבר. ניגוד עם סוג הראיה.", "correct_reason": "spurious = כוזבת/מזויפת. ניסוח רהוט לא מבטיח ראיה אמיתית.", "options_analysis": ["irrefutable = בלתי ניתנת להפרכה — סותר את הביקורת הגלומה ב''ultimately''", "נכון! spurious = כוזבת — יוצר ניגוד עם ''eloquently presented''", "conclusive = חד-משמעית — סותר את הביקורת", "overwhelming = מכריעה — סותר את הביקורת"]}', 1.37, 2.0, 0.25, 5, 'ai', NULL, true),
('268be636-b698-49a1-a12e-8eb80489702e', 'sentence_completion', 'The regime''s ___ crackdown on dissent drew international condemnation.', NULL, '[{"id": "a", "text": "lenient"}, {"id": "d", "text": "gentle"}, {"id": "b", "text": "draconian"}, {"id": "c", "text": "measured"}]'::jsonb, 2, '{"strategy": "drew international condemnation = משך גינוי בינלאומי. איזה סוג דיכוי מעורר גינוי כזה?", "correct_reason": "draconian = דרקוני/חמור מאוד. דיכוי חמור מעורר גינוי בינלאומי.", "options_analysis": ["lenient = מקל — סותר גינוי בינלאומי", "gentle = עדין — סותר לגמרי גינוי בינלאומי", "נכון! draconian = דרקוני — מסביר גינוי בינלאומי", "measured = מדוד — פחות סביר לעורר גינוי חריף"]}', 1.43, 2.0, 0.25, 5, 'ai', NULL, true),
('0f4bcb67-400f-4b6c-8098-c9a7b9c9f9f3', 'sentence_completion', 'The author''s ___ prose style demands close attention from the reader.', NULL, '[{"id": "c", "text": "simple"}, {"id": "b", "text": "accessible"}, {"id": "a", "text": "lucid"}, {"id": "d", "text": "dense"}]'::jsonb, 3, '{"strategy": "demands close attention = דורש תשומת לב רבה. איזה סגנון דורש קריאה מאומצת?", "correct_reason": "dense = צפוף/עמוס. סגנון צפוף דורש תשומת לב רבה.", "options_analysis": ["simple = פשוט — הפוך מדרישת תשומת לב", "accessible = נגיש — הפוך מדרישת מאמץ", "lucid = בהיר — הפוך, בהירות לא דורשת מאמץ קריאה", "נכון! dense = צפוף — מסביר את הצורך בתשומת לב רבה"]}', 1.59, 2.0, 0.25, 5, 'ai', NULL, true),
('4338fe0b-a718-430c-a5df-6156eee2b768', 'sentence_completion', 'The treaty''s ___ language left room for multiple, sometimes conflicting, interpretations.', NULL, '[{"id": "c", "text": "ambiguous"}, {"id": "d", "text": "unambiguous"}, {"id": "b", "text": "precise"}, {"id": "a", "text": "explicit"}]'::jsonb, 0, '{"strategy": "left room for multiple...interpretations = השאיר מקום לפרשנויות מרובות. איזו שפה עושה זאת?", "correct_reason": "ambiguous = דו-משמעית. שפה דו-משמעית מאפשרת פרשנויות מרובות.", "options_analysis": ["נכון! ambiguous = דו-משמעית — מסבירה פרשנויות מרובות וסותרות", "unambiguous = חד-משמעית — הפוך מ''multiple interpretations''", "precise = מדויקת — הפוך, מדויק לא משאיר מקום לפרשנות", "explicit = מפורשת — הפוך, מפורש לא משתמע לפרשנות"]}', 1.09, 2.0, 0.25, 5, 'ai', NULL, true),
('acbbda0c-bb02-4697-ae8b-15441f57c29d', 'sentence_completion', 'The board''s ___ handling of the crisis stood in sharp contrast to its usual decisiveness.', NULL, '[{"id": "d", "text": "assured"}, {"id": "c", "text": "vacillating"}, {"id": "b", "text": "resolute"}, {"id": "a", "text": "confident"}]'::jsonb, 1, '{"strategy": "sharp contrast to its usual decisiveness = ניגוד חד להחלטיות הרגילה. איזה סוג טיפול מנוגד להחלטיות?", "correct_reason": "vacillating = מהסס/מתנדנד. חוסר החלטיות מנוגד להחלטיות רגילה.", "options_analysis": ["assured = בטוח — לא מנוגד להחלטיות", "נכון! vacillating = מהסס — הניגוד המתבקש להחלטיות רגילה", "resolute = נחוש — זהה להחלטיות, לא מנוגד לה", "confident = בטוח בעצמו — לא מנוגד להחלטיות"]}', 1.35, 2.0, 0.25, 5, 'ai', NULL, true),
('461b7b08-482f-40b6-96de-04535ba85865', 'sentence_completion', 'The critic''s ___ review left no doubt about her disdain for the production.', NULL, '[{"id": "c", "text": "glowing"}, {"id": "d", "text": "complimentary"}, {"id": "a", "text": "scathing"}, {"id": "b", "text": "favorable"}]'::jsonb, 2, '{"strategy": "left no doubt about her disdain = לא השאיר ספק לגבי בוז. איזו ביקורת מבטאת בוז?", "correct_reason": "scathing = צורבת/קטלנית. ביקורת קטלנית מבטאת בוז ברור.", "options_analysis": ["glowing = זוהרת — הפוך מבוז", "complimentary = מחמיאה — הפוך מבוז", "נכון! scathing = קטלנית — מתאים לביטוי בוז ברור", "favorable = חיובית — הפוך מבוז"]}', 1.28, 2.0, 0.25, 5, 'ai', NULL, true),
('fea28ca6-0d76-44b0-9fdc-9b6a05b67ac1', 'sentence_completion', 'The scholar''s work is often praised for its ___ synthesis of disparate fields of study.', NULL, '[{"id": "b", "text": "disjointed"}, {"id": "c", "text": "chaotic"}, {"id": "d", "text": "fragmented"}, {"id": "a", "text": "seamless"}]'::jsonb, 3, '{"strategy": "synthesis of disparate fields = סינתזה של תחומים שונים. איזה סוג סינתזה ראוי לשבח?", "correct_reason": "seamless = חלקה/ללא תפרים. סינתזה חלקה של תחומים שונים ראויה לשבח.", "options_analysis": ["disjointed = מנותקת — הפוך מסינתזה חלקה", "chaotic = כאוטית — הפוך מסינתזה מוצלחת", "fragmented = מקוטעת — הפוך מסינתזה מוצלחת", "נכון! seamless = חלקה — מתאים לסינתזה מוצלחת של תחומים שונים"]}', 1.56, 2.0, 0.25, 5, 'ai', NULL, true),
('06a64e43-7c83-4b2b-ad08-bce9a26374e2', 'sentence_completion', 'The government''s ___ response to the economic crisis was criticized as too little, too late.', NULL, '[{"id": "d", "text": "tepid"}, {"id": "b", "text": "decisive"}, {"id": "c", "text": "immediate"}, {"id": "a", "text": "swift"}]'::jsonb, 0, '{"strategy": "too little, too late = מעט מדי, מאוחר מדי. איזו תגובה ראויה לביקורת כזו?", "correct_reason": "tepid = פושרת/חלשה. תגובה חלשה מתאימה לביקורת ''too little too late''.", "options_analysis": ["נכון! tepid = פושרת/חלשה — מתאים לביקורת ''too little''", "decisive = החלטית — הפוך מביקורת על חולשה", "immediate = מיידית — הפוך מ''too late''", "swift = מהירה — הפוך מ''too late''"]}', 1.12, 2.0, 0.25, 5, 'ai', NULL, true),
('7d154a3d-d62d-46bc-96ac-4520d22020ca', 'sentence_completion', 'The novel''s ___ ending frustrated readers who had hoped for a clear resolution.', NULL, '[{"id": "a", "text": "satisfying"}, {"id": "d", "text": "ambivalent"}, {"id": "c", "text": "conclusive"}, {"id": "b", "text": "definitive"}]'::jsonb, 1, '{"strategy": "frustrated readers who had hoped for a clear resolution = תסכל קוראים שקיוו לפתרון ברור. איזה סוג סיום מתסכל?", "correct_reason": "ambivalent = דו-ערכי/לא חד-משמעי. סיום לא ברור מתסכל קוראים שרצו בהירות.", "options_analysis": ["satisfying = מספק — הפוך מתסכול", "נכון! ambivalent = דו-ערכי — מסביר תסכול מחוסר בהירות", "conclusive = חד-משמעי — הפוך מתסכול על חוסר בהירות", "definitive = סופי וברור — הפוך מתסכול"]}', 1.42, 2.0, 0.25, 5, 'ai', NULL, true),
('9cba7804-fdce-45a7-918e-f170fe204785', 'sentence_completion', 'The professor''s ___ manner made students hesitant to ask questions in class.', NULL, '[{"id": "d", "text": "approachable"}, {"id": "c", "text": "welcoming"}, {"id": "b", "text": "intimidating"}, {"id": "a", "text": "warm"}]'::jsonb, 2, '{"strategy": "hesitant to ask questions = היססו לשאול שאלות. איזו התנהגות מרתיעה שאלות?", "correct_reason": "intimidating = מפחידה/מרתיעה. התנהגות מרתיעה גורמת להיסוס.", "options_analysis": ["approachable = נגיש — הפוך מהיסוס לשאול", "welcoming = מקבלת בברכה — הפוך מהיסוס", "נכון! intimidating = מרתיעה — מסבירה את ההיסוס", "warm = חמה — הפוך מהיסוס"]}', 1.57, 2.0, 0.25, 5, 'ai', NULL, true),
('c2cc73bc-5a52-4320-9a9f-d1e10ef1d492', 'sentence_completion', 'The diplomat''s ___ response avoided committing to any specific course of action.', NULL, '[{"id": "c", "text": "direct"}, {"id": "d", "text": "unequivocal"}, {"id": "b", "text": "decisive"}, {"id": "a", "text": "noncommittal"}]'::jsonb, 3, '{"strategy": "avoided committing to any specific course of action = נמנע ממחויבות לפעולה ספציפית. איזו תגובה עושה זאת?", "correct_reason": "noncommittal = לא מתחייבת/עמומה. תגובה כזו נמנעת ממחויבות.", "options_analysis": ["direct = ישירה — הפוך מהימנעות", "unequivocal = חד-משמעית — הפוך מהימנעות ממחויבות", "decisive = החלטית — הפוך מהימנעות ממחויבות", "נכון! noncommittal = לא מתחייבת — מדויק להימנעות ממחויבות"]}', 1.57, 2.0, 0.25, 5, 'ai', NULL, true),
('8ef3f1c8-a29c-4777-9741-32bde4ee17e4', 'restatement', 'The board''s endorsement, tepid as it was, still counted as a formal approval.', NULL, '[{"id": "c", "text": "The board''s lukewarm endorsement still constituted formal approval."}, {"id": "d", "text": "The endorsement was withdrawn before it became formal."}, {"id": "a", "text": "The board gave an enthusiastic and unqualified endorsement."}, {"id": "b", "text": "The board refused to give any endorsement at all."}]'::jsonb, 0, '{"strategy": "tepid...still counted = פושר...עדיין נחשב. ניגוד עם תוצאה.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["נכון! אותה משמעות בדיוק: תמיכה פושרת שעדיין נחשבה כאישור פורמלי", "סותר לגמרי — האישור כן ניתן", "סותר ''tepid''", "סותר ''still counted as a formal approval''"]}', 1.04, 2.0, 0.25, 5, 'ai', NULL, true),
('2c504cba-8826-48e0-8a11-bc1edef717ec', 'restatement', 'It would be an overstatement to say the reforms failed entirely, though their impact was modest at best.', NULL, '[{"id": "b", "text": "The reforms were a complete and total failure."}, {"id": "c", "text": "The reforms achieved only limited success, but were not a complete failure."}, {"id": "d", "text": "No reforms were ever attempted."}, {"id": "a", "text": "The reforms had an enormous, transformative impact."}]'::jsonb, 1, '{"strategy": "overstatement to say failed entirely...modest = הגזמה לומר שנכשלו לגמרי...צנוע. הערכה מתונה.", "correct_reason": "אותה הערכה מתונה בדיוק: לא כישלון מוחלט, אך גם לא הצלחה גדולה.", "options_analysis": ["סותר ''it would be an overstatement to say failed entirely''", "נכון! אותה הערכה מתונה בדיוק: הצלחה מוגבלת, לא כישלון מוחלט", "סותר לגמרי — הרפורמות כן בוצעו", "סותר ''modest at best''"]}', 1.22, 2.0, 0.25, 5, 'ai', NULL, true),
('e415a312-955f-481c-9638-1147370aa86f', 'restatement', 'Skeptics notwithstanding, the technology has proven remarkably resilient to obsolescence.', NULL, '[{"id": "b", "text": "No one was ever skeptical about this technology."}, {"id": "c", "text": "The technology became obsolete exactly as skeptics predicted."}, {"id": "d", "text": "Despite skeptics, the technology has remained surprisingly relevant and durable."}, {"id": "a", "text": "All skeptics were proven correct about the technology''s decline."}]'::jsonb, 2, '{"strategy": "skeptics notwithstanding...resilient = על אף הספקנים...עמידה. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''skeptics notwithstanding'' — היו ספקנים", "הפוך גמור — הטכנולוגיה דווקא עמידה, לא התיישנה", "נכון! אותה משמעות בדיוק: למרות הספקנים, הטכנולוגיה נותרה רלוונטית ועמידה", "סותר ''proven remarkably resilient to obsolescence''"]}', 1.27, 2.0, 0.25, 5, 'ai', NULL, true),
('80fb64b0-4e8f-48a6-8c7c-fde722ff3437', 'restatement', 'The findings, tentative though they may be, warrant further investigation.', NULL, '[{"id": "b", "text": "The findings were dismissed without any consideration."}, {"id": "c", "text": "No further investigation of the findings is warranted."}, {"id": "d", "text": "The findings are completely conclusive and need no further study."}, {"id": "a", "text": "Although the findings are preliminary, they justify additional research."}]'::jsonb, 3, '{"strategy": "tentative though they may be, warrant = ראשוניים ככל שיהיו, מצדיקים. ניגוד ותוצאה.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["סותר ''warrant further investigation''", "סותר ''warrant further investigation'' במפורש", "סותר ''tentative'' — הממצאים ראשוניים, לא חד-משמעיים", "נכון! אותה משמעות בדיוק: ראשוניים אך מצדיקים מחקר נוסף"]}', 1.21, 2.0, 0.25, 5, 'ai', NULL, true),
('7c96e425-e626-498a-b1ee-1c083f945d40', 'restatement', 'However well-meaning the policy was, its unintended consequences proved devastating.', NULL, '[{"id": "b", "text": "The policy''s good intentions led to devastating unintended consequences."}, {"id": "a", "text": "The policy''s consequences were entirely positive and intended."}, {"id": "d", "text": "The policy was poorly intentioned and had no consequences at all."}, {"id": "c", "text": "The policy had no unintended consequences whatsoever."}]'::jsonb, 0, '{"strategy": "however well-meaning...devastating = ככל שהייתה מבורכת בכוונותיה...הרסניות. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["נכון! אותה משמעות בדיוק: כוונות טובות שהובילו לתוצאות הרסניות בלתי מכוונות", "הפוך גמור — ''devastating'' סותר ''entirely positive''", "סותר ''well-meaning'' — הכוונות היו טובות", "סותר ''unintended consequences proved devastating''"]}', 1.34, 2.0, 0.25, 5, 'ai', NULL, true),
('6a88ea8e-d475-4e99-95d2-41ad178f4710', 'restatement', 'If anything, the new regulations made compliance more, not less, burdensome for small firms.', NULL, '[{"id": "d", "text": "The new regulations had no effect on small firms."}, {"id": "b", "text": "The new regulations increased the compliance burden on small firms."}, {"id": "a", "text": "The new regulations made compliance easier for small firms."}, {"id": "c", "text": "Small firms were exempt from the new regulations entirely."}]'::jsonb, 1, '{"strategy": "if anything...more, not less = אם כבר...יותר, לא פחות. הדגשת כיוון.", "correct_reason": "אותה משמעות בדיוק: הנטל גדל, לא קטן.", "options_analysis": ["סותר את ההשפעה שמתוארת במפורש", "נכון! אותה משמעות בדיוק: הנטל גדל, לא קטן", "הפוך — ''easier'' סותר ''more burdensome''", "סותר ''compliance more...burdensome for small firms''"]}', 1.6, 2.0, 0.25, 5, 'ai', NULL, true),
('818a3769-0c86-4595-ba99-0556ec22a005', 'restatement', 'The evidence, patchy as it is, nonetheless points toward a consistent pattern.', NULL, '[{"id": "c", "text": "There is no evidence available on this topic."}, {"id": "a", "text": "The evidence is complete and flawless."}, {"id": "d", "text": "Despite being incomplete, the evidence still suggests a consistent pattern."}, {"id": "b", "text": "The evidence points toward no discernible pattern at all."}]'::jsonb, 2, '{"strategy": "patchy as it is, nonetheless points = מקוטעת ככל שהיא, בכל זאת מצביעה. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר לגמרי — יש ראיות, גם אם מקוטעות", "סותר ''patchy'' — הראיות אינן שלמות", "נכון! אותה משמעות בדיוק: למרות שהיא חלקית, הראיה מצביעה על דפוס עקבי", "סותר ''points toward a consistent pattern''"]}', 1.15, 2.0, 0.25, 5, 'ai', NULL, true),
('98d5aa63-73f8-46cc-8e5d-c69cd73c0ed7', 'restatement', 'The committee stopped short of issuing a formal condemnation, opting instead for a mild rebuke.', NULL, '[{"id": "b", "text": "The committee took no action whatsoever."}, {"id": "a", "text": "The committee issued a strong formal condemnation."}, {"id": "c", "text": "The committee praised the actions in question."}, {"id": "d", "text": "The committee chose a mild rebuke rather than a formal condemnation."}]'::jsonb, 3, '{"strategy": "stopped short of...opting instead for = נמנעה מ-...ובחרה במקום זאת ב-. תיאור בחירה.", "correct_reason": "אותה בחירה בדיוק.", "options_analysis": ["סותר ''opting instead for a mild rebuke'' — כן ננקטה פעולה", "סותר ''stopped short of issuing a formal condemnation''", "הפוך גמור — הייתה נזיפה, לא שבח", "נכון! אותה בחירה בדיוק: נזיפה קלה במקום גינוי רשמי"]}', 1.02, 2.0, 0.25, 5, 'ai', NULL, true),
('aeb6834b-66f6-49f3-b893-62f87f9ff08c', 'restatement', 'The plan, ambitious to the point of recklessness, ultimately collapsed under its own weight.', NULL, '[{"id": "c", "text": "The plan was so ambitious that it became reckless, and it eventually failed."}, {"id": "b", "text": "The plan had no ambition whatsoever."}, {"id": "a", "text": "The plan succeeded precisely because of its recklessness."}, {"id": "d", "text": "The plan was modest and cautious, and it succeeded easily."}]'::jsonb, 0, '{"strategy": "ambitious to the point of recklessness...collapsed = שאפתני עד כדי פזיזות...קרס. הסבר כישלון.", "correct_reason": "אותה משמעות בדיוק.", "options_analysis": ["נכון! אותה משמעות בדיוק: שאפתנות שהפכה לפזיזות והובילה לקריסה", "סותר ''ambitious to the point of recklessness''", "סותר ''ultimately collapsed'' — התוכנית נכשלה, לא הצליחה", "הפוך — ''modest and cautious'' סותר ''ambitious to recklessness''"]}', 1.2, 2.0, 0.25, 5, 'ai', NULL, true),
('ac84008a-05dd-409d-ba1b-6d1c700dfe02', 'restatement', 'The senator''s remarks, calculated as they were, nonetheless struck many as sincere.', NULL, '[{"id": "d", "text": "No one paid attention to the senator''s remarks."}, {"id": "b", "text": "Despite being carefully calculated, the remarks seemed sincere to many."}, {"id": "a", "text": "The remarks were universally seen as insincere and manipulative."}, {"id": "c", "text": "The senator''s remarks were spontaneous and unplanned."}]'::jsonb, 1, '{"strategy": "calculated as they were, nonetheless struck as sincere = מחושבים ככל שהיו, בכל זאת נראו כנים. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''struck many'' — אנשים כן שמו לב", "נכון! אותה משמעות בדיוק: מחושבות אך נראו כנות לרבים", "סותר ''struck many as sincere''", "סותר ''calculated'' — הן היו מחושבות, לא ספונטניות"]}', 1.56, 2.0, 0.25, 5, 'ai', NULL, true),
('807d0548-4194-4ad8-bda9-a97c523fcc88', 'restatement', 'The proposal, for all its apparent simplicity, concealed a host of unresolved technical challenges.', NULL, '[{"id": "c", "text": "The proposal was as simple as it appeared, with no hidden complications."}, {"id": "d", "text": "The proposal had no technical challenges associated with it."}, {"id": "b", "text": "Despite seeming simple, the proposal hid many unresolved technical problems."}, {"id": "a", "text": "The technical challenges were fully resolved before the proposal was made."}]'::jsonb, 2, '{"strategy": "for all its apparent simplicity, concealed = על אף פשטותה לכאורה, הסתירה. ניגוד.", "correct_reason": "אותה משמעות בדיוק של ניגוד.", "options_analysis": ["סותר ''concealed a host of unresolved technical challenges''", "סותר את קיום האתגרים הטכניים שצוינו", "נכון! אותה משמעות בדיוק: פשטות לכאורה שהסתירה בעיות טכניות", "סותר ''unresolved technical challenges'' — הן לא נפתרו"]}', 1.58, 2.0, 0.25, 5, 'ai', NULL, true),
('49fbc769-89be-40c9-8a78-da0836cc4afe', 'reading_comprehension', 'What is the main idea of the passage?', '1dafb6c2-8aea-4bd5-b242-f11b48bb84eb', '[{"id": "c", "text": "The tragedy of the commons is inevitable and cannot be prevented"}, {"id": "b", "text": "Elinor Ostrom disproved the existence of shared resource problems entirely"}, {"id": "a", "text": "Garrett Hardin proved that all shared resources must be privatized"}, {"id": "d", "text": "The tragedy of the commons describes resource depletion, but Ostrom''s research showed it can be avoided through institutional design"}]'::jsonb, 3, '{"strategy": "שאלת רעיון מרכזי — הפסקה מציגה את המושג ואת האתגר שהציבה אליאנור אוסטרום לתפיסה שהוא בלתי נמנע.", "correct_reason": "כל הפסקה עוסקת בהגדרת התופעה ובממצאי אוסטרום שמראים שניתן למנוע אותה.", "options_analysis": ["סותר את מסקנת אוסטרום שמוצגת בפסקה", "הפוך — אוסטרום לא הפריכה את קיום הבעיה, אלא הראתה פתרונות", "הפוך — אוסטרום הראתה חלופות להפרטה ולשליטה מרכזית", "נכון! תיאור התופעה + ממצאי אוסטרום שמראים שניתן למנוע אותה = הנושא הכולל"]}', 1.34, 2.0, 0.25, 5, 'ai', NULL, true),
('d15c567a-cf14-4672-bcfe-c34c8fc8f03e', 'reading_comprehension', 'According to the passage, why is the rational choice for each herder to keep adding animals?', '1dafb6c2-8aea-4bd5-b242-f11b48bb84eb', '[{"id": "b", "text": "Because each herder bears only a fraction of the collective cost while capturing the full benefit"}, {"id": "a", "text": "Because the pasture is privately owned by one herder"}, {"id": "c", "text": "Because adding animals has no cost at all"}, {"id": "d", "text": "Because herders are required by law to add animals"}]'::jsonb, 0, '{"strategy": "שאלת סיבה — חפש את ההסבר הכלכלי בפסקה.", "correct_reason": "הפסקה אומרת: ''each individual bears only a fraction of the collective cost while capturing the full benefit of their own actions''.", "options_analysis": ["נכון! נאמר במפורש בפסקה", "לא נאמר בפסקה — הפסקה מתארת משאב משותף", "סותר את הפסקה — יש עלות, אך היא מתחלקת", "לא נאמר בפסקה"]}', 1.53, 2.0, 0.25, 5, 'ai', NULL, true),
('72b0d869-b2d4-466e-9fea-b4dc9900b350', 'reading_comprehension', 'The word "deplete" in the passage most closely means:', '1dafb6c2-8aea-4bd5-b242-f11b48bb84eb', '[{"id": "b", "text": "to legally regulate"}, {"id": "d", "text": "to use up or exhaust"}, {"id": "c", "text": "to carefully preserve"}, {"id": "a", "text": "to increase significantly"}]'::jsonb, 1, '{"strategy": "אוצר מילים בהקשר — ''deplete a shared resource'' מתייחס לדלדול משאב.", "correct_reason": "deplete = לדלדל/לרוקן/לנצל עד תום.", "options_analysis": ["לא קשור למשמעות המילה", "נכון! deplete = לדלדל/לנצל עד תום", "הפוך גמור — deplete הוא ניגוד לשימור", "הפוך גמור למשמעות המילה"]}', 1.43, 2.0, 0.25, 5, 'ai', NULL, true),
('ae14db21-19a6-4300-a2f0-e1bfa89c7042', 'reading_comprehension', 'What did Elinor Ostrom''s fieldwork demonstrate, according to the passage?', '1dafb6c2-8aea-4bd5-b242-f11b48bb84eb', '[{"id": "d", "text": "That government control is always necessary for managing resources"}, {"id": "b", "text": "That the tragedy of the commons never actually occurs"}, {"id": "c", "text": "That communities can develop self-governing institutions to manage resources sustainably"}, {"id": "a", "text": "That privatization is the only solution to shared resource problems"}]'::jsonb, 2, '{"strategy": "שאלת פרט — חפש את ממצאי המחקר של אוסטרום בפסקה.", "correct_reason": "הפסקה אומרת: ''communities have often developed sophisticated, self-governing institutions capable of managing shared resources sustainably''.", "options_analysis": ["הפוך — אוסטרום הראתה שאין צורך דווקא בשליטה ממשלתית מרכזית", "סותר את כל הפסקה — התופעה כן קיימת, אך ניתנת למניעה", "נכון! נאמר במפורש בפסקה", "הפוך — אוסטרום הראתה חלופה להפרטה, לא שהיא היחידה"]}', 1.09, 2.0, 0.25, 5, 'ai', NULL, true),
('4056771c-05fb-4407-a16f-e8148d05eec3', 'reading_comprehension', 'What did the passage say Ostrom''s research suggested about the tragedy of the commons?', '1dafb6c2-8aea-4bd5-b242-f11b48bb84eb', '[{"id": "d", "text": "That it is an inescapable fate for all shared resources"}, {"id": "c", "text": "That it was completely invented by Garrett Hardin without basis"}, {"id": "b", "text": "That it only applies to fishing industries"}, {"id": "a", "text": "That it results from a failure of institutional design, not an inevitable fate"}]'::jsonb, 3, '{"strategy": "שאלת פרט — חפש את המסקנה בסוף הפסקה.", "correct_reason": "הפסקה אומרת: ''the tragedy of the commons is not an inescapable fate but rather a failure of institutional design''.", "options_analysis": ["סותר את המסקנה המפורשת בסוף הפסקה", "לא נאמר בפסקה — התופעה מתוארת כאמיתית, רק לא בלתי נמנעת", "לא נאמר בפסקה — יש דוגמאות רבות נוספות", "נכון! נאמר במפורש בפסקה"]}', 1.42, 2.0, 0.25, 5, 'ai', NULL, true);